ruleSearch.lastChapter:
{{@@.even.0@a@text}} · {{@@.odd.2@text}}
<js>result.replace(/^(正文|VIP章节|最新章节)?(\s+|_)|[\(\{（｛【].*[求更谢乐发推票盟补加字Kk\/].*[\)\}）｝】]/g,'').replace(/^(\d+)、第.+章/,'第$1章').replace(/^(\d+)、\d+、/,'第$1章 ').replace(/^(\d+)、\d+/,'第$1章').replace(/^(第.+章)\s?\d+\s/,'$1 ').replace(/^(\d+)(、|. ?)/,'第$1章 ').replace(/^(第.+章)\s?第.+章/,'$1').replace(/第\s(.+)\s章/,'第$1章').replace(/.*(chapter|Chapter)\s?(\d+)\s?/,'$1 $2 ')
.replace(/(章)([^\s]+)(\s·)*/,'$1 $2$3').replace(/第([零一二三四五六七八九十百千]+)章/g,java.toNumChapter(result)).replace(/第0+/,'第').replace(/(第\d+章)\s\d+(.*)/,'$1$2')</js>

