    var d=r.data||{},rule=d.reward_rule||{},detail=rule.rule_details||{};
    var watched=Number(d.today_watch_count||0),total=Number(detail.total_required_count||d.total_required_count||0);
    var msg='今日广告进度：'+watched+(total?'/'+total:' 次');
