    else xySay('⚠️ 刷广告未成功\n'+String(r.message||'未知'),true);
  }catch(e){xySay('❌ 刷广告失败\n'+String(e.message||e),true)}
}
function xyAutoWatchAll(){
  XY.setEnv(java,source);
  try{
    xyRequireAdLogin();
    var pending=xyPendingAd();
    if(pending){xyClearAd();xySay('检测到上次残留任务，已清理，请重新点击',true);return}
    var done=XY.getTodayAdCount();
    var remaining=Math.max(0,3-done);
    if(remaining===0){xySay('✅ 今日已成功刷3次\n无需再刷',true);return}
    xySay('开始自动刷广告\n今日已完成'+done+'次，还需刷'+remaining+'次',false);
    var r=XY.watchAdAll(function(cur,total,success,prevDone){
      xySay('正在刷第'+cur+'/'+total+'次\n✅ 已成功'+success+'次',false);
    });
    var msg;
    if(r.total===0){
      msg='✅ 今日已成功刷3次\n无需再刷';
    }else{
      var totalDone=done+r.success;
      msg='✅ 刷广告完成\n今日共成功'+totalDone+'/3次';
      if(r.success>0)msg+='\n本次新刷成功'+r.success+'次';
      if(r.success<r.total){
        var failed=r.results.filter(function(x){return !x.success});
        if(failed.length)msg+='\n⚠️ 失败原因：'+String(failed[0].message||'');
      }
      if(totalDone>=3)msg+='\n今日额度已用完';
    }
    xySay(msg,true);
  }catch(e){xySay('❌ 自动刷广告失败\n'+String(e.message||e),true)}
}
function login(){xyLogin()}

