var SQ_P_CHINFO = "/sqan/sqapi/bff/api/v1/reader/chapterinfo";
function SQ_S(x){return ""+(x===undefined||x===null?"":x);}
function SQ_trim(s){return SQ_S(s).replace(/^\s+|\s+$/g,"");}
function SQ_plain(s){return SQ_trim(SQ_S(s).replace(/<[^>]*>/g,"").replace(/&nbsp;/g," ").replace(/&amp;/g,"&").replace(/&lt;/g,"<").replace(/&gt;/g,">").replace(/&quot;/g,'"').replace(/\s+/g," "));}
function SQ_wan(v){var n=Number(v)||0;if(n>=1e8)return (Math.round(n/1e6)/100)+"亿字";if(n>=1e4)return (Math.round(n/1e3)/10)+"万字";return n>0?n+"字":"";}
function SQ_status(v){return SQ_S(v)==="2"?"完结":"连载";}
function SQ_tagStr(m){var a=m.tags||m.tagList||[];var o=[],i;
 if(typeof a==="string")return SQ_plain(a);
 for(i=0;i<a.length;i++){var t=a[i];o.push(SQ_plain(typeof t==="string"?t:(t&&(t.tagName||t.name))||""));}
 return o.filter(function(x){return x}).join(",");}
function SQ_bid(u){var s=SQ_S(u),m;
 m=s.match(/get_book_content_([0-9]{1,12})_([0-9]{1,20})_/);if(m)return m[1];
 m=s.match(/(?:\/book\/|\/sqbook\/|bid=|bookId=)([0-9]{1,12})/);return m?m[1]:"";}
function SQ_cid(u){var s=SQ_S(u),m;
 m=s.match(/get_book_content_[0-9]{1,12}_([0-9]{1,20})_/);if(m)return m[1];
 m=s.match(/(?:cid=|sqch\/\d+\/)([0-9]{1,20})/);return m?m[1]:"";}
function SQ_bookUrl(id,S){try{return SQ_web(S)+"/book/"+id+".html"}catch(e){return SQ_WEB_ALT[0]+"/book/"+id+".html";}}
function SQ_chUrl(bid,cid,S){try{return SQ_cdnHost(S)+"/httpserver/filecache/get_book_content_"+bid+"_"+cid+"_3111111111_0_0.html"}catch(e){return SQ_CDN_ALT[0]+"/httpserver/filecache/get_book_content_"+bid+"_"+cid+"_3111111111_0_0.html";}}
function SQ_gv(S,k,d){var v="";try{v=SQ_S(S.get(k)||"");}catch(e){}
 if(!v||v==="null"||v==="undefined")v=d||"";return SQ_S(v);}
function SQ_web(S){
 var w=SQ_gv(S,"sqWeb",SQ_WEB).replace(/\/$/,"");
 var ok=false,i;for(i=0;i<SQ_WEB_ALT.length;i++)if(w===SQ_WEB_ALT[i])ok=true;
 if(!ok)w=SQ_WEB_ALT[0];
 return w;}
function SQ_cdnHost(S){
 var c=SQ_gv(S,"sqCdn","https://c1.shuqireader.com").replace(/\/$/,"");
 var ok2=false,i;for(i=0;i<SQ_CDN_ALT.length;i++)if(c===SQ_CDN_ALT[i])ok2=true;
 if(!ok2)c=SQ_CDN_ALT[0];
 return c;}
function SQ_put(S,k,v){try{S.put(k,SQ_S(v));}catch(e){try{java.put(k,SQ_S(v));}catch(e2){}}}
function SQ_webGet(Jv,url){var o={timeout:12000,headers:{"User-Agent":SQ_UA}};
 return SQ_S(Jv.ajax(url+","+JSON.stringify(o)));}
function SQ_api(Jv,S,path,biz,uid){return SQ_post(Jv,S,path,biz,uid);}
function SQ_searchUrl(Jv,S,kw,pg){
 var biz=[["page","searchResultV3"],["query",SQ_S(kw)],["timestamp",String(Date.now())]];
 var r=SQ_req(SQ_P_SEARCH,biz,null,S);
