function SQ_searchBooks(resp,S){S=S||{get:function(){return ""}};
 var d={};try{d=(resp&&typeof resp==="object")?resp:JSON.parse(SQ_S(resp));}catch(e){return [];}
 var mods=(d.data&&d.data.moduleInfos)||[],out=[],seen={},i;
 for(i=0;i<mods.length;i++){
  var b=mods[i]&&mods[i].book;if(!b||!b.bookId)continue;
  var id=SQ_S(b.bookId);if(seen[id])continue;seen[id]=1;
  var kind=[];
  var bottom=SQ_plain(b.bottomText||"");if(bottom)kind.push(bottom);
  var tags=SQ_tagStr(b);if(tags)kind.push(tags);
  out.push({name:SQ_plain(b.bookName||b.displayBookName),author:SQ_plain(b.authorName),
   bookUrl:SQ_bookUrl(id,S),coverUrl:SQ_S(b.imgUrl||""),
   intro:SQ_plain(b.desc),kind:kind.join(","),wordCount:SQ_wan(b.wordCount),
   lastChapter:"",status:SQ_status(b.state)});
 }
 return out;
}
function SQ_detail(Jv,S,rawUrl){
 var bid=SQ_bid(rawUrl);if(!bid)throw new Error("书旗：无效书籍ID");
 var info=null;
 try{var r=SQ_api(Jv,S,SQ_P_TITLE,[["bookId",bid]]);
  var b=(r&&r.data&&r.data.bookInfo)||null;
  if(b&&b.bookName){
   var score=(r.data&&r.data.scoreInfo)||{};
   var kind=[SQ_S(b.secCateName||""),SQ_tagStr(b),SQ_status(b.serialState),score.bookScore?score.bookScore+"分":"",SQ_wan(b.wordCount)].filter(function(x){return x});
   info={name:SQ_plain(b.bookName),author:SQ_plain(b.authorName),
    intro:SQ_plain(b.briefIntro||b.desc||b.intro),kind:kind.join(","),
    coverUrl:SQ_S(b.coverUrl||b.imgUrl||""),wordCount:SQ_wan(b.wordCount),
    lastChapter:SQ_plain((b.lastChapter&&b.lastChapter.chapterName)||b.latestChapterName||""),
    tocUrl:SQ_bookUrl(bid,S)};
  }
 }catch(e){}
 if(!info){
  try{var h=SQ_webGet(Jv,SQ_web(S)+"/book/"+bid+".html");
   var ti=(h.match(/<title>([\s\S]{0,160}?)<\/title>/)||[])[1]||"";
   var mt=ti.match(/《([^》]+)》/);var nm=mt?mt[1]:"";
   var au=(h.match(/作者[：:]\s*([^<\s,，]{1,20})/)||[])[1]||"";
   var iv=(h.match(/简介[：:]?([\s\S]{0,400}?)<\/p>/)||[])[1]||"";
   info={name:nm||"书籍"+bid,author:au,intro:SQ_plain(iv),kind:"",coverUrl:"",wordCount:"",lastChapter:"",tocUrl:SQ_bookUrl(bid,S)};
  }catch(e2){throw new Error("书旗：详情获取失败 "+bid);}
 }
 return info;
}
function SQ_toc(Jv,S,rawUrl){
 var bid=SQ_bid(rawUrl);if(!bid)throw new Error("书旗：无效书籍ID");
 var h="";
 try{h=SQ_webGet(Jv,SQ_web(S)+"/chapter?bid="+bid);}catch(e){}
 if(h.length>5000&&h.indexOf("cid=")>=0){
  var rows=[],seen={},re=/href="\/reader\?bid=\d+&(?:amp;)?cid=(\d+)"[^>]*>([\s\S]*?)<\/a>/g,m;
  while((m=re.exec(h))!==null){
   var cid=m[1];if(seen[cid])continue;seen[cid]=1;
   var inner=SQ_S(m[2]).replace(/<i[^>]*>[\s\S]*?<\/i>/gi," ").replace(/<[^>]*>/g," ");
   inner=SQ_plain(inner).replace(/^\d+[.、]\s*/,"");
   if(!inner)continue;
   rows.push({title:inner,url:SQ_chUrl(bid,cid,S)});
   if(rows.length>20000)break;
  }
  if(rows.length)return rows;
 }
 var base=0,first="",total=0;
 try{var cr=SQ_api(Jv,S,SQ_P_CHINFO,[["bookId",bid]],SQ_CIUID);
  var ch=(cr&&cr.data&&cr.data.chapter)||{};
  base=Number(ch.chapterId)||0;first=SQ_plain(ch.name||"");}catch(e){}
 try{var br=SQ_api(Jv,S,SQ_P_TITLE,[["bookId",bid]]);
  total=Number(br&&br.data&&br.data.bookInfo&&br.data.bookInfo.chapterTotalNum)||0;}catch(e2){}
 if(!base||!total||total>20000)throw new Error("书旗：目录不可用（H5与递推均失败），请稍后重试");
 var out=[],i;for(i=0;i<total;i++){
  out.push({title:i===0?(first||"第1章"):("第"+(i+1)+"章"),url:SQ_chUrl(bid,String(base+i),S)});
 }
 return out;
}
function SQ_cdnParse(body){
 var s=SQ_S(body),i=s.indexOf("("),j=s.lastIndexOf(")"),inner=i>0&&j>i?s.slice(i+1,j):s;
 try{var a=JSON.parse(inner);var c=SQ_S(a&&a[0]&&a[0].content);
  if(!c)return "";
  return SQ_trim(c.replace(/<br\s*\/?>/gi,"\n").replace(/&nbsp;/g," ").replace(/<[^>]*>/g,"")
   .replace(/&amp;/g,"&").replace(/&lt;/g,"<").replace(/&gt;/g,">").replace(/&quot;/g,'"'));
 }catch(e){return "";}
}
function SQ_rot13(s){return SQ_S(s).replace(/[a-zA-Z]/g,function(c){var b=c<="Z"?65:97;return String.fromCharCode((c.charCodeAt(0)-b+13)%26+b);});}
function SQ_ciDecode(s){var r=SQ_rot13(s).replace(/\s+/g,"");
 try{return SQ_u8s(SQ_b64d(r)).replace(/<br\s*\/?>/gi,"\n");}catch(e){return "";}}
function SQ_content(Jv,S,rawUrl){
 var bid=SQ_bid(rawUrl),cid=SQ_cid(rawUrl);
 if(!bid||!cid)throw new Error("书旗：章节地址无效");
 var note=[],i,f,h,sch,url,txt;
 var pref=SQ_cdnHost(S).split("//")[1];
 var hs=SQ_CDN_HOSTS.slice();
 hs.sort(function(a,b){return (a===pref?-1:0)-(b===pref?-1:0)});
 for(sch=0;sch<2;sch++){
  var scheme=sch===0?"https":"http";
  for(h=0;h<hs.length;h++){
   for(f=0;f<SQ_CDN_FLAGS.length;f++){
    url=scheme+"://"+hs[h]+"/httpserver/filecache/get_book_content_"+bid+"_"+cid+"_"+SQ_CDN_FLAGS[f]+"_0_0.html";
    try{var b=SQ_webGet(Jv,url);txt=SQ_cdnParse(b);
     if(txt.length>30)return txt;note.push(SQ_CDN_HOSTS[h]+"/"+SQ_CDN_FLAGS[f]+":空");
    }catch(e){note.push(SQ_CDN_HOSTS[h]+"/"+SQ_CDN_FLAGS[f]+":失败");}
   }
  }
 }
 try{var cr=SQ_api(Jv,S,SQ_P_CHINFO,[["bookId",bid],["chapterId",cid]],SQ_CIUID);
  var enc=SQ_S(cr&&cr.data&&cr.data.chapter&&cr.data.chapter.content);
  if(enc){var dec=SQ_ciDecode(enc);if(dec.length>30)return dec;}
 }catch(e){note.push("chapterinfo:"+SQ_S(e).slice(0,40));}
 throw new Error("书旗：本章正文不可用（"+(cid)+"）。"+(note.length?note.slice(0,3).join("; "):"可能需登录或为付费章"));
}
function SQ_explore(Jv,S,rawUrl,pg){
 var u=SQ_S(rawUrl);
 var mp=u.match(/[?&]page=([0-9]+)/);var p=mp?Number(mp[1]):(Number(pg)||1);
 var path="",m;
 if((m=u.match(/[?&]rank=([A-Za-z]+)/)))path="/ranklist?rank="+m[1]+"&page="+p;
 else if(/[?&](?:sz|fc|wd|tm|st|store|sqs)=/.test(u)||u.indexOf("/store")>=0){
  var q=u.indexOf("?")>=0?u.slice(u.indexOf("?")+1).replace(/&amp;/g,"&"):"";
  q=q.replace(/[?&]?page=[0-9]+/g,"").replace(/^&+|&+$/g,"");
  var keep=[],kv=q.split("&"),i0;
  for(i0=0;i0<kv.length;i0++){if(/^(sz|fc|wd|tm|st)=/.test(kv[i0]))keep.push(kv[i0]);}
  path="/store?"+(keep.length?keep.join("&")+"&":"")+"page="+p;
 }
 else path="/rank?page="+p;
 var web=SQ_web(S);
 var h="";
 try{h=SQ_webGet(Jv,web+path);}catch(e){}
 if(h.length<2000)return [];
 var out=[],seen={},re,i2;
 if(path.indexOf("/ranklist")===0||path.indexOf("/rank?")===0){
  re=/<li class="clearfix">([\s\S]*?)<\/li>/g;
  var mm;
  while((mm=re.exec(h))!==null){
   var li=SQ_S(mm[1]);
   var mb=li.match(/\/book\/(\d+)\.html/);if(!mb||seen[mb[1]])continue;seen[mb[1]]=1;
   var title=(li.match(/<h3>([\s\S]*?)<\/h3>/)||[])[1]||"";
   var img=(li.match(/<img[^>]*src="([^"]+)"/)||[])[1]||"";
   var au=(li.match(/class="bkuser-icon"[^>]*>[\s\S]*?<a[^>]*>([\s\S]*?)<\/a>/)||[])[1]||"";
   var cate=(li.match(/class="bkcate-icon">([\s\S]*?)<\/span>/)||[])[1]||"";
   var des=(li.match(/class="ranklist-des">([\s\S]*?)<\/p>/)||[])[1]||"";
   var tags=(li.match(/class="ranklist-tag">([\s\S]*?)<\/p>/)||[])[1]||"";
   var tg=SQ_plain(tags.replace(/<[^>]*>/g," "));
   out.push({name:SQ_plain(title),author:SQ_plain(au),bookUrl:SQ_bookUrl(mb[1],S),
    coverUrl:SQ_S(img),intro:SQ_plain(des),kind:[SQ_plain(cate),tg].filter(function(x){return x}).join(",")});
  }
 }else{
  var lis=h.split('<li');
  for(i2=1;i2<lis.length;i2++){
   var li=SQ_S(lis[i2].split('</li>')[0]);
   if(li.indexOf('store-tag')<0)continue;
   var mb2=li.match(/\/book\/(\d+)\.html/);if(!mb2||seen[mb2[1]])continue;seen[mb2[1]]=1;
   var nm=(li.match(/<h3[^>]*>([\s\S]*?)<\/h3>/)||[])[1]||'';
   if(!nm){var mt2=li.match(/<a[^>]*href="\/book\/\d+\.html"[^>]*title="([^"]*)"/);if(mt2)nm=mt2[1];}
   var im=(li.match(/<img[^>]*class="cover"[^>]*src="([^"]+)"/)||li.match(/<img[^>]*src="([^"]+)"/)||[])[1]||'';
   var des=(li.match(/class="store-des">([\s\S]*?)<\/p>/)||[])[1]||'';
   var au=(li.match(/class="store-tag[^>]*>[\s\S]*?<a[^>]*>([\s\S]*?)<\/a>/)||[])[1]||'';
   au=SQ_plain(au).replace(/^作者[：:]\s*/,'');
   var cate=(li.match(/class="store-tag[^>]*>[\s\S]*?<span>([\s\S]*?)<\/span>/)||[])[1]||'';
   if(!nm)continue;
   out.push({name:SQ_plain(nm),author:au,bookUrl:SQ_bookUrl(mb2[1],S),coverUrl:SQ_S(im),
    intro:SQ_plain(des),kind:SQ_plain(cate)});
  }
 }
 return out;
}
function SQ_speedKey(host){return "sqsp_"+SQ_S(host).replace(/[^a-z0-9]/gi,"").slice(0,24);}
function SQ_speedTest(Jv,S){
 var res=[],i,best="",bm=99999999;
 for(i=0;i<SQ_ALL_LINES.length;i++){
  var host=SQ_ALL_LINES[i];
  var isCdn=SQ_CDN_ALT.indexOf(host)>=0;
  var probe=isCdn?host+"/httpserver/filecache/get_book_content_34078_2180322_3111111111_0_0.html"
                  :host+"/ranklist?rank=boyClick";
  var t0=Date.now(),ok=false,ms=0;
  try{var h=SQ_webGet(Jv,probe);
   ms=Date.now()-t0;
   ok=isCdn?(h.indexOf("success_jsonpCallback")>=0&&h.indexOf("\\u3000")>=0)
           :(h.length>5000&&h.indexOf("ranklist-ul")>=0&&h.indexOf("访问被拒绝")<0);
  }catch(e){ms=Date.now()-t0;}
  var st=ok?ms+"ms":"超时/不支持";
  SQ_put(S,SQ_speedKey(host),st);
  res.push({host:host,kind:isCdn?"CDN":"H5",ms:ms,ok:ok,st:st});
  if(ok&&!isCdn&&ms<bm){bm=ms;best=host;}
 }
 if(best){SQ_put(S,SQ_speedKey(best),"⚡"+bm+"ms");SQ_put(S,"sqWeb",best);}
 return {best:best,bm:bm,rows:res};
}
