function SQ_uiSpeed(jv){
 SQ_T(jv,'⏳ 开始逐站测速（2 条 H5 + 2 条 CDN，约 5~30 秒），请稍候…');
 var hs=SQ_HOSTS(),msg='📊 测速结果：',best='',bm=99999999,i;
 for(i=0;i<hs.length;i++){
