var SQ_UA = "okhttp/3.12.13";
var SQ_H5UA = "okhttp/3.12.13";
var SQ_B64C = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
var SQ_PUB = [
["soft_id","1"],["user_id",SQ_UID],["userId",SQ_UID],["ver","261013"],
["subVer","sqrelease"],["appVer","12.7.0.268"],["theme","day"],["platform","an"],
["placeid","1069"],["sdk","32"],["cpu","x86_64"],["pkg_cpu","arm64-v8a"],["wh","900x1600"],
["msv","3"],["vc","5d73"],["mod","BVL-AN16"],["manufacturer","HONOR"],["brand","HONOR"],
["net_type","wifi"],["net_type_str","wifi"],["first_placeid","src1069"],["aak","a3a840"],
["utype","pre_vip"],["net","4"],["net_env","4"],["permissionType","0"],["personalized","1"],
["contentRecom","1"],["scene_code",""],["rom","12"],["sqUniqDeviceId",""],["utdid",""],
["sn",""],["umidtoken",""],["otdd",""]];
var SQ_ORDER = ["soft_id","user_id","userId","ver","subVer","appVer","theme","platform","placeid",
"sdk","cpu","pkg_cpu","wh","msv","enc","vc","mod","manufacturer","brand","net_type","net_type_str",
"first_placeid","aak","utype","net","net_env","permissionType","personalized","contentRecom",
"scene_code","rom","sqUniqDeviceId","utdid","sn","umidtoken","otdd"];
var SQ_NOSIGN = ["sign","key","_public","_reqid","_beta","_","X","XNEBULAXMLHTTPREQUEST","callbackUrl"];
function SQ_b64d(s){s=String(s).replace(/[^A-Za-z0-9+\/=]/g,"");var o=[],i=0,c1,c2,c3,c4;
 while(i<s.length){c1=SQ_B64C.indexOf(s.charAt(i++));c2=SQ_B64C.indexOf(s.charAt(i++));
  c3=SQ_B64C.indexOf(s.charAt(i++));c4=SQ_B64C.indexOf(s.charAt(i++));
  if(c2<0)break;o.push(((c1<<2)|(c2>>4))&255);
  if(c3>=0){o.push((((c2&15)<<4)|(c3>>2))&255);
   if(c4>=0)o.push((((c3&3)<<6)|c4)&255);}}
 return o;}
function SQ_b64e(bs){var o="",i=0,L=bs.length,a,b,c,n;
 while(i<L){a=bs[i++]&255;b=i<L?bs[i++]&255:-1;c=i<L?bs[i++]&255:-1;
  n=(a<<16)|((b<0?0:b)<<8)|(c<0?0:c);
  o+=SQ_B64C.charAt((n>>18)&63)+SQ_B64C.charAt((n>>12)&63)+
     (b<0?"=":SQ_B64C.charAt((n>>6)&63))+(c<0?"=":SQ_B64C.charAt(n&63));}
 return o;}
function SQ_u8(s){var o=[],i=0,c,c2,cp;s=String(s);
 for(i=0;i<s.length;i++){c=s.charCodeAt(i);
  if(c<128)o.push(c);
  else if(c<2048)o.push(192|(c>>6),128|(c&63));
  else if(c>=0xD800&&c<=0xDBFF&&i+1<s.length){c2=s.charCodeAt(++i);
   cp=0x10000+((c-0xD800)<<10)+(c2-0xDC00);
   o.push(240|(cp>>18),128|((cp>>12)&63),128|((cp>>6)&63),128|(cp&63));}
  else o.push(224|(c>>12),128|((c>>6)&63),128|(c&63));}
 return o;}
function SQ_u8s(bs){var s="",i=0,c,b1,b2,b3,cp;
 while(i<bs.length){c=bs[i++]&255;
  if(c<128)s+=String.fromCharCode(c);
  else if(c<224){b1=bs[i++]&255;s+=String.fromCharCode(((c&31)<<6)|(b1&63));}
  else if(c<240){b1=bs[i++]&255;b2=bs[i++]&255;s+=String.fromCharCode(((c&15)<<12)|((b1&63)<<6)|(b2&63));}
  else{b1=bs[i++]&255;b2=bs[i++]&255;b3=bs[i++]&255;
   cp=(((c&7)<<18)|((b1&63)<<12)|((b2&63)<<6)|(b3&63))-0x10000;
   s+=String.fromCharCode(0xD800+(cp>>10),0xDC00+(cp&1023));}}
 return s;}
function SQ_uri(s){return encodeURIComponent(String(s));}
function SQ_pubEnc(s){return SQ_uri(s).replace(/\+/g,"%20").replace(/\*/g,"%2A").replace(/%7E/g,"~");}
function SQ_md5(str){
 var bs=SQ_u8(String(str)),i,j,L=bs.length;
 var SA=[7,12,17,22,7,12,17,22,7,12,17,22,7,12,17,22,
  5,9,14,20,5,9,14,20,5,9,14,20,5,9,14,20,
  4,11,16,23,4,11,16,23,4,11,16,23,4,11,16,23,
  6,10,15,21,6,10,15,21,6,10,15,21,6,10,15,21];
 var KT=[];for(i=0;i<64;i++)KT[i]=Math.floor(Math.abs(Math.sin(i+1))*4294967296);
 function rol(x,c){return (x<<c)|(x>>>(32-c));}
 function add(a,b){var l=(a&65535)+(b&65535),h=(a>>>16)+(b>>>16)+(l>>>16);return ((h<<16)|(l&65535))>>>0;}
 var bitLen=L*8;
 bs.push(128);
 while(bs.length%64!==56)bs.push(0);
 var hi=Math.floor(bitLen/4294967296),lo=bitLen>>>0;
 bs.push(lo&255,(lo>>>8)&255,(lo>>>16)&255,(lo>>>24)&255,
        hi&255,(hi>>>8)&255,(hi>>>16)&255,(hi>>>24)&255);
 var a0=0x67452301,b0=0xefcdab89,c0=0x98badcfe,d0=0x10325476;
 for(i=0;i<bs.length;i+=64){
  var M=[];for(j=0;j<16;j++){var q=i+j*4;M[j]=(bs[q]|(bs[q+1]<<8)|(bs[q+2]<<16)|(bs[q+3]<<24))>>>0;}
  var A=a0,B=b0,C=c0,D=d0,F,g,tmp;
  for(j=0;j<64;j++){
   if(j<16){F=(B&C)|((~B)&D);g=j;}
   else if(j<32){F=(D&B)|((~D)&C);g=(5*j+1)%16;}
   else if(j<48){F=B^C^D;g=(3*j+5)%16;}
   else{F=C^(B|(~D));g=(7*j)%16;}
   F=add(add(add(A,F),KT[j]),M[g]);
   tmp=D;D=C;C=B;B=add(B,rol(F,SA[j]));A=tmp;}
  a0=add(a0,A);b0=add(b0,B);c0=add(c0,C);d0=add(d0,D);}
 function hx(n){var s="",k;for(k=0;k<4;k++){var v=(n>>>(k*8))&255;s+=(v<16?"0":"")+v.toString(16);}return s;}
 return hx(a0)+hx(b0)+hx(c0)+hx(d0);}
function SQ_enc18(uid,ts){ts=String(ts);while(ts.length<13)ts="2"+ts;if(ts.length>13)ts=ts.slice(0,13);
 var n=Number(uid)||0;if(n===0)n=24697;
 var k=Number(ts.charAt(1)+ts.charAt(3)+ts.charAt(5)+ts.charAt(8)+ts.charAt(6))||0;
 var p=k===0?12347*n:k*n;
 var tail=String(p).slice(-5);
 return tail+ts;}
function SQ_sign(pairs){var a=[],i,k,v;
 for(i=0;i<pairs.length;i++){k=pairs[i][0];v=pairs[i][1];
  if(SQ_NOSIGN.indexOf(k)>=0)continue;a.push([k,String(v)]);}
 var has=false;for(i=0;i<a.length;i++)if(a[i][0]==="sqSv")has=true;
 if(!has)a.push(["sqSv",SQ_SQSV]);
 a.sort(function(x,y){return x[0]<y[0]?-1:(x[0]>y[0]?1:0);});
 var raw="";for(i=0;i<a.length;i++)raw+=a[i][0]+"="+SQ_uri(a[i][1])+"&";
 raw+="skey="+SQ_SKEY;return SQ_md5(raw);}
function SQ_pubStr(uid,enc,dev){var m={},i,k;
 for(i=0;i<SQ_PUB.length;i++)m[SQ_PUB[i][0]]=SQ_PUB[i][1];
 for(k in dev)if(dev.hasOwnProperty(k))m[k]=dev[k];
 m.user_id=uid;m.userId=uid;m.platform="2";m.enc=enc;
 var o="";for(i=0;i<SQ_ORDER.length;i++){k=SQ_ORDER[i];
  if(m[k]!==undefined)o+=k+"="+SQ_pubEnc(m[k])+"&";}
 return o;}
function SQ_xorB64(bytes){var ks=SQ_KS(),o=[],i,n=bytes.length<ks.length?bytes.length:ks.length;
 for(i=0;i<n;i++)o.push((bytes[i]&255)^(ks[i]&255));
 return SQ_b64e(o);}
var SQ_KS_CACHE=null;
function SQ_KS(){if(!SQ_KS_CACHE)SQ_KS_CACHE=SQ_b64d(SQ_KSB64);return SQ_KS_CACHE;}
function SQ_rnd(n,hex){var C="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789",H="0123456789abcdef",s="";
 for(var i=0;i<n;i++)s+=(hex?H:C).charAt(Math.floor(Math.random()*(hex?16:62)));return s;}
function SQ_newDev(){return {sqUniqDeviceId:SQ_rnd(22,0),utdid:SQ_rnd(28,0),sn:SQ_rnd(16,1),
 umidtoken:SQ_rnd(40,1),otdd:SQ_rnd(22,0)};}
function SQ_dev(S){var v="";try{v=String(S.get("sqDev")||"");}catch(e){}
 if(v&&v.length>10&&v!=="null"){try{var d=JSON.parse(v);if(d&&d.sn)return d;}catch(e2){}}
 var d2=SQ_newDev();try{S.put("sqDev",JSON.stringify(d2));}catch(e3){}return d2;}
function SQ_req(path,biz,uid,S,ts){uid=uid||SQ_UID;ts=ts||String(Date.now());
 var dev=SQ_dev(S);var enc=SQ_enc18(uid,ts);
 var m={},i,k,v;
 for(i=0;i<SQ_PUB.length;i++)m[SQ_PUB[i][0]]=SQ_PUB[i][1];
 for(k in dev)if(dev.hasOwnProperty(k))m[k]=dev[k];
 m.user_id=uid;m.userId=uid;m.platform="an";m.enc=enc;m.timestamp=ts;
 for(i=0;i<biz.length;i++)m[biz[i][0]]=String(biz[i][1]);
 m.isTeenMode="0";m.sqSv=SQ_SQSV;
 var pairs=[];for(k in m)if(m.hasOwnProperty(k))pairs.push([k,m[k]]);
 m.sign=SQ_sign(pairs);m.key="sq_app_gateway";
 var plain=SQ_u8(JSON.stringify(m));
 var body="data="+SQ_uri(SQ_xorB64(plain));
 var pub=SQ_pubStr(uid,enc,dev);
 var hdr={"content-type":"application/x-www-form-urlencoded","user-agent":SQ_UA,
  "x-sq-req-platform":"an","x-sq-s-key":"23011413","x-sq-sv":"3.0",
  "x-sq-public":SQ_xorB64(SQ_u8(pub)),"x-sq-req-encrypt":"sdk",
  "x-sq-req-encrypt-param":"x-sq-public","x-sq-api-encrypt":"1"};
 return {url:SQ_HOST+path,option:{method:"POST",body:body,headers:hdr,timeout:15000}};}
function SQ_post(Jv,S,path,biz,uid){var r=SQ_req(path,biz,uid,S);
 var raw=String(Jv.ajax(r.url+","+JSON.stringify(r.option)));
 try{return JSON.parse(raw);}catch(e){throw new Error("书旗接口返回异常: "+raw.slice(0,120));}}
function SQ_get(Jv,url,ua){var o={timeout:12000,headers:{"User-Agent":ua||SQ_H5UA}};
 return String(Jv.ajax(url+","+JSON.stringify(o)));}
var SQ_WEB = "https://www.shuqi.com";
var SQ_WEB_ALT = ["https://www.shuqi.com","https://shuqi.com"];
var SQ_CDN_ALT = ["https://c1.shuqireader.com","https://c2.shuqireader.com"];
var SQ_ALL_LINES = SQ_WEB_ALT.concat(SQ_CDN_ALT);
var SQ_CDN_HOSTS = ["c1.shuqireader.com","c2.shuqireader.com"];
var SQ_CDN_FLAGS = ["3111111111","2111111111"];
var SQ_P_SEARCH = "/sqan/render/render/search/native_v3";
var SQ_P_TITLE = "/sqan/sqapi/bff/api/v1/reader/titlepage";
var SQ_P_CHINFO = "/sqan/sqapi/bff/api/v1/reader/chapterinfo";
function SQ_S(x){return ""+(x===undefined||x===null?"":x);}
function SQ_trim(s){return SQ_S(s).replace(/^\s+|\s+$/g,"");}
function SQ_plain(s){return SQ_trim(SQ_S(s).replace(/<[^>]*>/g,"").replace(/&nbsp;/g," ").replace(/&amp;/g,"&").replace(/&lt;/g,"<").replace(/&gt;/g,">").replace(/&quot;/g,'"').replace(/\s+/g," "));}
function SQ_wan(v){var n=Number(v)||0;if(n>=1e8)return (Math.round(n/1e6)/100)+"亿字";if(n>=1e4)return (Math.round(n/1e3)/10)+"万字";return n>0?n+"字":"";}
function SQ_status(v){return SQ_S(v)==="2"?"完结":"连载";}
function SQ_tagStr(m){var a=m.tags||m.tagList||[];var o=[],i;
 if(typeof a==="string")return SQ_plain(a);
 for(i=0;i<a.length;i++){var t=a[i];o.push(SQ_plain(typeof t==="string"?t:(t&&(t.tagName||t.name))||""));}
 return o.filter(function(x){return x}).join(",");}
function SQ_bid(u){var s=SQ_S(u),m;
 m=s.match(/get_book_content_([0-9]{1,12})_([0-9]{1,20})_/);if(m)return m[1];
 m=s.match(/(?:\/book\/|\/sqbook\/|bid=|bookId=)([0-9]{1,12})/);return m?m[1]:"";}
function SQ_cid(u){var s=SQ_S(u),m;
 m=s.match(/get_book_content_[0-9]{1,12}_([0-9]{1,20})_/);if(m)return m[1];
 m=s.match(/(?:cid=|sqch\/\d+\/)([0-9]{1,20})/);return m?m[1]:"";}
function SQ_bookUrl(id,S){try{return SQ_web(S)+"/book/"+id+".html"}catch(e){return SQ_WEB_ALT[0]+"/book/"+id+".html";}}
function SQ_chUrl(bid,cid,S){try{return SQ_cdnHost(S)+"/httpserver/filecache/get_book_content_"+bid+"_"+cid+"_3111111111_0_0.html"}catch(e){return SQ_CDN_ALT[0]+"/httpserver/filecache/get_book_content_"+bid+"_"+cid+"_3111111111_0_0.html";}}
function SQ_gv(S,k,d){var v="";try{v=SQ_S(S.get(k)||"");}catch(e){}
 if(!v||v==="null"||v==="undefined")v=d||"";return SQ_S(v);}
function SQ_web(S){
 var w=SQ_gv(S,"sqWeb",SQ_WEB).replace(/\/$/,"");
 var ok=false,i;for(i=0;i<SQ_WEB_ALT.length;i++)if(w===SQ_WEB_ALT[i])ok=true;
 if(!ok)w=SQ_WEB_ALT[0];
 return w;}
function SQ_cdnHost(S){
 var c=SQ_gv(S,"sqCdn","https://c1.shuqireader.com").replace(/\/$/,"");
 var ok2=false,i;for(i=0;i<SQ_CDN_ALT.length;i++)if(c===SQ_CDN_ALT[i])ok2=true;
 if(!ok2)c=SQ_CDN_ALT[0];
 return c;}
function SQ_put(S,k,v){try{S.put(k,SQ_S(v));}catch(e){try{java.put(k,SQ_S(v));}catch(e2){}}}
function SQ_webGet(Jv,url){var o={timeout:12000,headers:{"User-Agent":SQ_UA}};
 return SQ_S(Jv.ajax(url+","+JSON.stringify(o)));}
function SQ_api(Jv,S,path,biz,uid){return SQ_post(Jv,S,path,biz,uid);}
function SQ_searchUrl(Jv,S,kw,pg){
 var biz=[["page","searchResultV3"],["query",SQ_S(kw)],["timestamp",String(Date.now())]];
 var r=SQ_req(SQ_P_SEARCH,biz,null,S);
 return r.url+","+JSON.stringify(r.option);
}
function SQ_searchBooks(resp,S){S=S||{get:function(){return ""}};
 var d={};try{d=(resp&&typeof resp==="object")?resp:JSON.parse(SQ_S(resp));}catch(e){return [];}
 var mods=(d.data&&d.data.moduleInfos)||[],out=[],seen={},i;
 for(i=0;i<mods.length;i++){
  var b=mods[i]&&mods[i].book;if(!b||!b.bookId)continue;
  var id=SQ_S(b.bookId);if(seen[id])continue;seen[id]=1;
  var kind=[];
  var bottom=SQ_plain(b.bottomText||"");if(bottom)kind.push(bottom);
  var tags=SQ_tagStr(b);if(tags)kind.push(tags);
  out.push({name:SQ_plain(b.bookName||b.displayBookName),author:SQ_plain(b.authorName),
   bookUrl:SQ_bookUrl(id,S),coverUrl:SQ_S(b.imgUrl||""),
   intro:SQ_plain(b.desc),kind:kind.join(","),wordCount:SQ_wan(b.wordCount),
   lastChapter:"",status:SQ_status(b.state)});
 }
 return out;
}
function SQ_detail(Jv,S,rawUrl){
 var bid=SQ_bid(rawUrl);if(!bid)throw new Error("书旗：无效书籍ID");
 var info=null;
 try{var r=SQ_api(Jv,S,SQ_P_TITLE,[["bookId",bid]]);
  var b=(r&&r.data&&r.data.bookInfo)||null;
  if(b&&b.bookName){
   var score=(r.data&&r.data.scoreInfo)||{};
   var kind=[SQ_S(b.secCateName||""),SQ_tagStr(b),SQ_status(b.serialState),score.bookScore?score.bookScore+"分":"",SQ_wan(b.wordCount)].filter(function(x){return x});
   info={name:SQ_plain(b.bookName),author:SQ_plain(b.authorName),
    intro:SQ_plain(b.briefIntro||b.desc||b.intro),kind:kind.join(","),
    coverUrl:SQ_S(b.coverUrl||b.imgUrl||""),wordCount:SQ_wan(b.wordCount),
    lastChapter:SQ_plain((b.lastChapter&&b.lastChapter.chapterName)||b.latestChapterName||""),
    tocUrl:SQ_bookUrl(bid,S)};
  }
 }catch(e){}
 if(!info){
  try{var h=SQ_webGet(Jv,SQ_web(S)+"/book/"+bid+".html");
   var ti=(h.match(/<title>([\s\S]{0,160}?)<\/title>/)||[])[1]||"";
   var mt=ti.match(/《([^》]+)》/);var nm=mt?mt[1]:"";
   var au=(h.match(/作者[：:]\s*([^<\s,，]{1,20})/)||[])[1]||"";
   var iv=(h.match(/简介[：:]?([\s\S]{0,400}?)<\/p>/)||[])[1]||"";
   info={name:nm||"书籍"+bid,author:au,intro:SQ_plain(iv),kind:"",coverUrl:"",wordCount:"",lastChapter:"",tocUrl:SQ_bookUrl(bid,S)};
  }catch(e2){throw new Error("书旗：详情获取失败 "+bid);}
 }
 return info;
}
function SQ_h5Rows(seg,bid,S){
 var rows=[],seen={},re=/href="\/reader\?bid=\d+&(?:amp;)?cid=(\d+)"[^>]*>([\s\S]*?)<\/a>/g,m;
 while((m=re.exec(seg))!==null){
  var cid=m[1];if(seen[cid])continue;seen[cid]=1;
  var inner=SQ_S(m[2]).replace(/<i[^>]*>[\s\S]*?<\/i>/gi," ").replace(/<[^>]*>/g," ");
  inner=SQ_plain(inner).replace(/^\d+[.、]\s*/,"");
  if(!inner)continue;
  rows.push({pos:m.index,title:inner,url:SQ_chUrl(bid,cid,S)});
  if(rows.length>20000)break;
 }
 return rows;
}
function SQ_volMark(name,title){
 var vn=SQ_S(name);if(!vn)return title;
 if(SQ_S(title).indexOf(vn)>=0)return title;
 return "【"+vn+"】"+title;
}
function SQ_openToc(Jv,S,bid){
 var KEY="37e81a9d8f02596e1b895d07c171d5c9",UID="8000000";
 var ts=String(Math.floor(Date.now()/1000));
 var q="bookId="+bid+"&user_id="+UID+"&timestamp="+ts+"&sign="+SQ_md5(String(bid)+ts+UID+KEY);
 var raw="";
 try{raw=SQ_webGet(Jv,"https://content.shuqireader.com/openapi/book/chapterlist?shuqi_h5=205&platform=0&"+q);}catch(e){}
 if(!raw||raw.length<200){try{raw=SQ_webGet(Jv,"https://ocean.shuqireader.com/api/bcspub/qswebapi/book/chapterlist?_=&"+q);}catch(e2){}}
 var d={};try{d=JSON.parse(raw);}catch(e3){return [];}
 if(String(d.state)!=="200"&&String(d.status)!=="200")return [];
 var dt=d.data||{},cls=dt.chapterList||[],vols=[],i,j;
 for(i=0;i<cls.length;i++){
  var v=cls[i]||{},a=v.volumeList||v.chapterList||v.chapter||[],rows=[];
  for(j=0;j<a.length;j++){
   var c=a[j]||{},cid=SQ_S(c.chapterId||c.cid||"");
   if(!cid)continue;
   var nm=SQ_plain(c.chapterName||c.name||c.title||"");
   if(!nm)nm="第"+(rows.length+1)+"章";
   rows.push({title:nm,url:SQ_chUrl(bid,cid,S)});
   if(rows.length>20000)break;
  }
  if(rows.length)vols.push({name:SQ_plain(v.volumeName||v.name||""),rows:rows});
 }
 if(!vols.length)return [];
 var multi=vols.length>=2,out=[];
 for(i=0;i<vols.length;i++){
  var vv=vols[i],vname=multi?vv.name:"";
  for(j=0;j<vv.rows.length;j++){
   var t=vv.rows[j].title;
   if(j===0&&vname)t=SQ_volMark(vname,t);
   out.push({title:t,url:vv.rows[j].url});
  }
 }
 return out;
}
function SQ_toc(Jv,S,rawUrl){
 var bid=SQ_bid(rawUrl);if(!bid)throw new Error("书旗：无效书籍ID");
 var h="";
 try{h=SQ_webGet(Jv,SQ_web(S)+"/chapter?bid="+bid);}catch(e){}
 if(h.length>5000&&h.indexOf("cid=")>=0){
  var rows=SQ_h5Rows(h,bid,S);
  if(rows.length){
   var marks=[],vm=/<div class="vol_name"[^>]*>\s*<span>([\s\S]*?)<\/span>/g,mm;
   while((mm=vm.exec(h))!==null)marks.push({pos:mm.index,name:SQ_plain(mm[1])});
   var out=[],k,vi,fk,firstSet={};
   if(marks.length>=2){
    for(vi=0;vi<marks.length;vi++){
     fk=-1;
     for(k=0;k<rows.length;k++)if(rows[k].pos>=marks[vi].pos&&(vi+1>=marks.length||rows[k].pos<marks[vi+1].pos)){fk=k;break;}
     if(fk>=0&&marks[vi].name)firstSet[fk]=marks[vi].name;
    }
   }
   for(k=0;k<rows.length;k++){
    var t=rows[k].title;
    if(firstSet[k])t=SQ_volMark(firstSet[k],t);
    out.push({title:t,url:rows[k].url});
   }
   return out;
  }
 }
 return SQ_openToc(Jv,S,bid);
}
function SQ_cdnParse(body){
 var s=SQ_S(body),i=s.indexOf("("),j=s.lastIndexOf(")"),inner=i>0&&j>i?s.slice(i+1,j):s;
 try{var a=JSON.parse(inner);var c=SQ_S(a&&a[0]&&a[0].content);
  if(!c)return "";
  return SQ_trim(c.replace(/<br\s*\/?>/gi,"\n").replace(/&nbsp;/g," ").replace(/<[^>]*>/g,"")
   .replace(/&amp;/g,"&").replace(/&lt;/g,"<").replace(/&gt;/g,">").replace(/&quot;/g,'"'));
 }catch(e){return "";}
}
function SQ_rot13(s){return SQ_S(s).replace(/[a-zA-Z]/g,function(c){var b=c<="Z"?65:97;return String.fromCharCode((c.charCodeAt(0)-b+13)%26+b);});}
function SQ_ciDecode(s){var r=SQ_rot13(s).replace(/\s+/g,"");
 try{return SQ_u8s(SQ_b64d(r)).replace(/<br\s*\/?>/gi,"\n");}catch(e){return "";}}
function SQ_content(Jv,S,rawUrl){
 var bid=SQ_bid(rawUrl),cid=SQ_cid(rawUrl);
 if(!bid||!cid)throw new Error("书旗：章节地址无效");
 var note=[],i,f,h,sch,url,txt;
 var pref=SQ_cdnHost(S).split("//")[1];
 var hs=SQ_CDN_HOSTS.slice();
 hs.sort(function(a,b){return (a===pref?-1:0)-(b===pref?-1:0)});
 for(sch=0;sch<2;sch++){
  var scheme=sch===0?"https":"http";
  for(h=0;h<hs.length;h++){
   for(f=0;f<SQ_CDN_FLAGS.length;f++){
    url=scheme+"://"+hs[h]+"/httpserver/filecache/get_book_content_"+bid+"_"+cid+"_"+SQ_CDN_FLAGS[f]+"_0_0.html";
    try{var b=SQ_webGet(Jv,url);txt=SQ_cdnParse(b);
     if(txt.length>30)return txt;note.push(SQ_CDN_HOSTS[h]+"/"+SQ_CDN_FLAGS[f]+":空");
    }catch(e){note.push(SQ_CDN_HOSTS[h]+"/"+SQ_CDN_FLAGS[f]+":失败");}
   }
  }
 }
 try{var cr=SQ_api(Jv,S,SQ_P_CHINFO,[["bookId",bid],["chapterId",cid]],SQ_CIUID);
  var enc=SQ_S(cr&&cr.data&&cr.data.chapter&&cr.data.chapter.content);
  if(enc){var dec=SQ_ciDecode(enc);if(dec.length>30)return dec;}
 }catch(e){note.push("chapterinfo:"+SQ_S(e).slice(0,40));}
 throw new Error("书旗：本章正文不可用（"+(cid)+"）。"+(note.length?note.slice(0,3).join("; "):"可能需登录或为付费章"));
}
function SQ_explore(Jv,S,rawUrl,pg){
 var u=SQ_S(rawUrl);
 var mp=u.match(/[?&]page=([0-9]+)/);var p=mp?Number(mp[1]):(Number(pg)||1);
 var path="",m;
 if((m=u.match(/[?&]rank=([A-Za-z]+)/)))path="/ranklist?rank="+m[1]+"&page="+p;
 else if(/[?&](?:sz|fc|wd|tm|st|store|sqs)=/.test(u)||u.indexOf("/store")>=0){
  var q=u.indexOf("?")>=0?u.slice(u.indexOf("?")+1).replace(/&amp;/g,"&"):"";
  q=q.replace(/[?&]?page=[0-9]+/g,"").replace(/^&+|&+$/g,"");
  var keep=[],kv=q.split("&"),i0;
  for(i0=0;i0<kv.length;i0++){if(/^(sz|fc|wd|tm|st)=/.test(kv[i0]))keep.push(kv[i0]);}
  path="/store?"+(keep.length?keep.join("&")+"&":"")+"page="+p;
 }
 else path="/rank?page="+p;
 var web=SQ_web(S);
 var h="";
 try{h=SQ_webGet(Jv,web+path);}catch(e){}
 if(h.length<2000)return [];
 var out=[],seen={},re,i2;
 if(path.indexOf("/ranklist")===0||path.indexOf("/rank?")===0){
  re=/<li class="clearfix">([\s\S]*?)<\/li>/g;
  var mm;
  while((mm=re.exec(h))!==null){
   var li=SQ_S(mm[1]);
   var mb=li.match(/\/book\/(\d+)\.html/);if(!mb||seen[mb[1]])continue;seen[mb[1]]=1;
   var title=(li.match(/<h3>([\s\S]*?)<\/h3>/)||[])[1]||"";
   var img=(li.match(/<img[^>]*src="([^"]+)"/)||[])[1]||"";
   var au=(li.match(/class="bkuser-icon"[^>]*>[\s\S]*?<a[^>]*>([\s\S]*?)<\/a>/)||[])[1]||"";
   var cate=(li.match(/class="bkcate-icon">([\s\S]*?)<\/span>/)||[])[1]||"";
   var des=(li.match(/class="ranklist-des">([\s\S]*?)<\/p>/)||[])[1]||"";
   var tags=(li.match(/class="ranklist-tag">([\s\S]*?)<\/p>/)||[])[1]||"";
   var tg=SQ_plain(tags.replace(/<[^>]*>/g," "));
   out.push({name:SQ_plain(title),author:SQ_plain(au),bookUrl:SQ_bookUrl(mb[1],S),
    coverUrl:SQ_S(img),intro:SQ_plain(des),kind:[SQ_plain(cate),tg].filter(function(x){return x}).join(",")});
  }
 }else{
  var lis=h.split('<li');
  for(i2=1;i2<lis.length;i2++){
   var li=SQ_S(lis[i2].split('</li>')[0]);
   if(li.indexOf('store-tag')<0)continue;
   var mb2=li.match(/\/book\/(\d+)\.html/);if(!mb2||seen[mb2[1]])continue;seen[mb2[1]]=1;
   var nm=(li.match(/<h3[^>]*>([\s\S]*?)<\/h3>/)||[])[1]||'';
   if(!nm){var mt2=li.match(/<a[^>]*href="\/book\/\d+\.html"[^>]*title="([^"]*)"/);if(mt2)nm=mt2[1];}
   var im=(li.match(/<img[^>]*class="cover"[^>]*src="([^"]+)"/)||li.match(/<img[^>]*src="([^"]+)"/)||[])[1]||'';
   var des=(li.match(/class="store-des">([\s\S]*?)<\/p>/)||[])[1]||'';
   var au=(li.match(/class="store-tag[^>]*>[\s\S]*?<a[^>]*>([\s\S]*?)<\/a>/)||[])[1]||'';
   au=SQ_plain(au).replace(/^作者[：:]\s*/,'');
   var cate=(li.match(/class="store-tag[^>]*>[\s\S]*?<span>([\s\S]*?)<\/span>/)||[])[1]||'';
   if(!nm)continue;
   out.push({name:SQ_plain(nm),author:au,bookUrl:SQ_bookUrl(mb2[1],S),coverUrl:SQ_S(im),
    intro:SQ_plain(des),kind:SQ_plain(cate)});
  }
 }
 return out;
}
function SQ_speedKey(host){return "sqsp_"+SQ_S(host).replace(/[^a-z0-9]/gi,"").slice(0,24);}
function SQ_speedTest(Jv,S){
 var res=[],i,best="",bm=99999999;
 for(i=0;i<SQ_ALL_LINES.length;i++){
  var host=SQ_ALL_LINES[i];
  var isCdn=SQ_CDN_ALT.indexOf(host)>=0;
  var probe=isCdn?host+"/httpserver/filecache/get_book_content_34078_2180322_3111111111_0_0.html"
                  :host+"/ranklist?rank=boyClick";
  var t0=Date.now(),ok=false,ms=0;
  try{var h=SQ_webGet(Jv,probe);
   ms=Date.now()-t0;
   ok=isCdn?(h.indexOf("success_jsonpCallback")>=0&&h.indexOf("\\u3000")>=0)
           :(h.length>5000&&h.indexOf("ranklist-ul")>=0&&h.indexOf("访问被拒绝")<0);
  }catch(e){ms=Date.now()-t0;}
  var st=ok?ms+"ms":"超时/不支持";
